#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void group_norm_kernel(
    const half* __restrict__ input,
    half* __restrict__ output,
    const half* __restrict__ weight,
    const half* __restrict__ bias,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    int batch_size,
    int num_features,
    int num_groups,
    int elements_per_group,
    int total_elements
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) return;

    // Determine which feature channel this element belongs to
    int feature_idx = (idx / elements_per_group) % num_features;
    int group_idx = feature_idx / (num_features / num_groups);

    // Get mean and variance for this group
    float group_mean = mean[group_idx];
    float group_var = var[group_idx];

    // Calculate normalized value
    float eps = 1e-5f;
    float inv_std = rsqrtf(group_var + eps);

    // Get input value
    float input_val = __half2float(input[idx]);

    // Normalize and scale
    float normalized = (input_val - group_mean) * inv_std;

    // Apply affine transformation
    float result = normalized * __half2float(weight[feature_idx]) + __half2float(bias[feature_idx]);

    output[idx] = __float2half(result);
}

// Helper function to compute mean and variance for each group
__global__ void compute_stats_kernel(
    const half* __restrict__ input,
    float* __restrict__ mean,
    float* __restrict__ var,
    int batch_size,
    int num_features,
    int num_groups,
    int elements_per_group,
    int total_elements
) {
    int group_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (group_idx >= num_groups) return;

    // Shared memory for reduction
    extern __shared__ float shared_data[];

    int elements_per_feature = batch_size * elements_per_group;
    int start_idx = group_idx * elements_per_feature;

    // Initialize accumulators
    double sum = 0.0;
    double sum_sq = 0.0;

    // Process all elements in this group
    for (int i = 0; i < elements_per_feature; i++) {
        if (start_idx + i < total_elements) {
            float val = __half2float(input[start_idx + i]);
            sum += val;
            sum_sq += val * val;
        }
    }

    // Store partial sums in shared memory
    shared_data[threadIdx.x] = (float)sum;
    __syncthreads();

    // Reduction within block
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared_data[threadIdx.x] += shared_data[threadIdx.x + stride];
        }
        __syncthreads();
    }

    // Store final results
    if (threadIdx.x == 0) {
        float group_sum = shared_data[0];
        float group_sum_sq = 0.0;

        // Compute sum of squares
        for (int i = 0; i < elements_per_feature; i++) {
            if (start_idx + i < total_elements) {
                float val = __half2float(input[start_idx + i]);
                group_sum_sq += val * val;
            }
        }

        float group_mean = group_sum / (float)elements_per_feature;
        float group_var = group_sum_sq / (float)elements_per_feature - group_mean * group_mean;

        mean[group_idx] = group_mean;
        var[group_idx] = group_var;
    }
}

void launch_group_norm(
    const half* input,
    half* output,
    const half* weight,
    const half* bias,
    const float* mean,
    const float* var,
    int batch_size,
    int num_features,
    int num_groups,
    int elements_per_group,
    int total_elements
) {
    // Launch stats computation
    int num_blocks = (num_groups + 255) / 256;
    int threads_per_block = 256;
    size_t shared_mem_size = threads_per_block * sizeof(float);

    compute_stats_kernel<<<num_blocks, threads_per_block, shared_mem_size>>>(
        input, mean, var, batch_size, num_features, num_groups, elements_per_group, total_elements
    );

    // Launch normalization
    num_blocks = (total_elements + 255) / 256;
    threads_per_block = 256;

    group_norm_kernel<<<num_blocks, threads_per_block>>>(
        input, output, weight, bias, mean, var, 
        batch_size, num_features, num_groups, elements_per_group, total_elements
    );
}
"""

# Python wrapper
def create_model_new():
    # Load CUDA extension
    module = load_inline(
        name="group_norm_ext",
        cpp_sources="",
        cuda_sources=cuda_source,
        functions=["launch_group_norm"],
        verbose=False
    )

    class ModelNew(torch.nn.Module):
        def __init__(self, num_features: int, num_groups: int):
            super().__init__()
            self.num_features = num_features
            self.num_groups = num_groups
            self.weight = torch.nn.Parameter(torch.ones(num_features, dtype=torch.float16))
            self.bias = torch.nn.Parameter(torch.zeros(num_features, dtype=torch.float16))

        def forward(self, x: torch.Tensor) -> torch.Tensor:
            batch_size = x.shape[0]
            elements_per_group = x.numel() // (batch_size * self.num_groups)

            # Allocate temporary buffers for mean and variance
            mean = torch.empty(self.num_groups, dtype=torch.float32, device=x.device)
            var = torch.empty(self.num_groups, dtype=torch.float32, device=x.device)

            # Call CUDA kernel
            module.launch_group_norm(
                x.data_ptr(),
                x.data_ptr(),  # Overwrite input with output
                self.weight.data_ptr(),
                self.bias.data_ptr(),
                mean.data_ptr(),
                var.data_ptr(),
                batch_size,
                self.num_features,
                self.num_groups,
                elements_per_group,
                x.numel()
            )

            return x

    return ModelNew

# Create the model class
